import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should show username required error when both fields are empty', async ({ page }) => {
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Username is required');
  });

  test('should show password required error when only username is entered', async ({ page }) => {
    const usernameInput = page.getByLabel(/username/i);
    await usernameInput.fill('standard_user');

    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Password is required');
  });
});
